{"file_text": "<nav class="mb-4">
    <div class="d-flex justify-content-between position-relative step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep && !isCompleted;

            <div class="text-center flex-fill step-item">
                <button type="button"
                        class="btn rounded-circle step-circle @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50")"
                        disabled="@(isFuture && !isCompleted)"
                        @onclick="() => OnStepClicked.InvokeAsync(step)"
                        style="width: 40px; height: 40px; padding: 0;">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepNames[step]
                </div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = [];
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}
