@page "/apply"
@rendermode InteractiveServer

@using sv_4fd01df0b2524665bd86113d0cee1765.Models
@using sv_4fd01df0b2524665bd86113d0cee1765.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   StepNames="_stepNames"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personalInfo" OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="_references" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="OnCoverLetterChanged"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep @ref="_reviewStep"
                        Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEdit="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();
    private readonly List<string> _stepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    private ReviewStep? _reviewStep;

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < _stepNames.Count - 1)
            _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
            _currentStep = step;
    }

    private void OnCoverLetterChanged(string value)
    {
        _coverLetter = value;
    }

    private async Task SubmitApplication()
    {
        if (_reviewStep is null) return;

        _reviewStep.SetSubmitting(true);

        try
        {
            var application = new JobApplication(
                _personalInfo.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            _completedSteps.Add(_currentStep);
            _reviewStep.SetSubmitted(id);
        }
        catch (Exception ex)
        {
            _reviewStep.SetError($"Submission failed: {ex.Message}. Please try again.");
        }
    }
}

